from lib import *
S = SS('f167')
R = J('f167'); pl = R['pool']; st = R['small_timeout']; ov = R['over']
steps = [
    step(f"1 个 gunicorn worker × 32 线程,每个请求在 PostgreSQL 里要 20 ms,300 个请求、32 并发:pool_size=1 时 {pl['1'][0]:.0f} 请求/秒、平均 {pl['1'][1]:.0f} ms;2 个 {pl['2'][0]:.0f}、{pl['2'][1]:.0f} ms;5 个 {pl['5'][0]:.0f}、{pl['5'][1]:.0f} ms;10 个 {pl['10'][0]:.0f}、{pl['10'][1]:.0f} ms;20 个 {pl['20'][0]:.0f}、{pl['20'][1]:.0f} ms。吞吐几乎正比于池大小(理想上限是 pool_size ÷ 0.02 秒,实测约为它的 82–86%),线程再多也没用——32 个线程里大部分在池子外面等连接。数据库调用占大头的服务,池大小就是并发上限。", b=bars([['pool 1', pl['1'][0], f"{pl['1'][0]:.0f}"], ['pool 5', pl['5'][0], f"{pl['5'][0]:.0f}"], ['pool 10', pl['10'][0], f"{pl['10'][0]:.0f}"], ['pool 20', pl['20'][0], f"{pl['20'][0]:.0f}"]], pl['20'][0], done=[0, 1, 2, 3]), t=tl(S(1)), done=lidx(S(1), '         1 ', '         2 ', '         5 ', '        10 ', '        20 '), kv=KV([['pool 1 → 20', f"{pl['1'][0]:.0f} → {pl['20'][0]:.0f} 请求/秒"], ['平均延迟', f"{pl['1'][1]:.0f} → {pl['20'][1]:.0f} ms"]], ['pool 1 → 20'])),
    step(f"池太小又设了等待超时:pool_size=2、max_overflow=0、pool_timeout=0.5 秒,32 并发的 20 ms 请求,300 个请求里成功 {st[0]} 个、失败 {st[1]} 个,全部是 TimeoutError(等不到连接)。池太小加上短的等待超时,高峰时大部分请求直接失败而不是变慢。要么放大池,要么限制并发(线程数不要远大于池),要么加大 pool_timeout 让请求排队。", t=tl(S(2)), mark=lidx(S(2), '300 个请求'), kv=KV([['池太小 + 超时 0.5 秒', f'成功 {st[0]} / 300,其余 TimeoutError']], ['池太小 + 超时 0.5 秒'])),
    step(f"池大小乘以进程数超过数据库的 max_connections:PostgreSQL max_connections=20(其中 3 个保留给超级用户),4 个 worker × pool_size 10 = 最多 40 个连接。400 个请求里成功 {ov[0]} 个、失败 {ov[1]} 个,失败原因是「connection failed: connection to server ... failed」(FATAL: sorry, too many clients already);此时连我用来查看连接数的 psql 都连不上,同样报「sorry, too many clients already」。每个进程的池各自占坑,互相看不到——总连接数 = worker 数 × (pool_size + max_overflow),要小于数据库的 max_connections。", t=tl(S(3)), mark=lidx(S(3), '400 个请求'), kv=KV([['总连接数', 'worker × (pool_size + max_overflow)'], ['超过 max_connections', '新连接被拒,连监控也连不上']], ['总连接数'])),
]
A = mkartf('f167', 167, 'Flask,SQLAlchemy,连接池大小,max_connections,真实验证,动画演示',
    f'在真实的 PostgreSQL 上实测连接池大小:每个 20 ms 的数据库请求,pool_size 从 1 到 20 吞吐从 {pl["1"][0]:.0f} 增长到 {pl["20"][0]:.0f} 请求/秒;池 2 加 0.5 秒超时时 300 个请求只成功 {st[0]} 个;4 个 worker × pool 10 超过数据库 max_connections=20 时 {ov[1]} 个请求失败且监控连接也被拒。',
    '连接池该设多大?池太小会怎样?worker 数乘池大小超过数据库连接上限又会怎样?这篇用真实的 gunicorn 与 PostgreSQL 把三个问题逐个量出来(池的机制本身见第 91、92 篇)。',
    [(f'{pl["1"][0]:.0f} → {pl["20"][0]:.0f}', 'pool_size 从 1 到 20 时的请求/秒(每个请求 20 ms)'), (f'{st[0]} / 300', 'pool_size=2、pool_timeout=0.5 秒时 32 并发下成功的请求数'), (f'{ov[1]} 个失败', '4 个 worker × pool 10 超过 max_connections=20 时失败的请求数(400 个里)')],
    [('池大小决定并发', '<p>上一篇:<a href="flask-worker-timeout.html">Worker Timeout</a>;下一篇:<a href="flask-cache-hit-rate.html">缓存命中率</a>。</p>'), ('池太小加短超时', None), ('超过数据库连接上限', '<p>PostgreSQL 是自己起的实例,max_connections 设成 20 来演示。</p>')],
    steps, [ENV_F + '。Flask-SQLAlchemy 3.1.1、psycopg 3.3.6、自己起的 PostgreSQL(max_connections=20)、gunicorn gthread', '没有验证:PgBouncer 等外部连接池、max_overflow 的取值效果、真实查询耗时分布下的最优池大小、读写分离的多个池、数据库侧每个连接的内存成本'], '连接池大小', panels=[('t', 'term', '实验输出'), ('b', 'bars', '请求/秒'), ('kv', 'kv', '要点')])
